import React, { useState, useEffect } from "react";
import api from "../services/api";

function RestockProduct({ user }) {
  const [products, setProducts] = useState([]);
  const [selectedId, setSelectedId] = useState("");
  const [quantity, setQuantity] = useState(0);
  const [costPrice, setCostPrice] = useState(0);
  const [sellingPrice, setSellingPrice] = useState(0);
  const [message, setMessage] = useState("");

  useEffect(() => {
    async function fetchProducts() {
      const res = await api.get("/products");
      setProducts(res.data);
    }
    fetchProducts();
  }, []);

  const handleRestock = async (e) => {
    e.preventDefault();
    try {
      const res = await api.post(`/products/${selectedId}/restock`, {
        quantity_added: quantity,
        cost_price: costPrice,
        selling_price: sellingPrice,
        restocked_by: user.id,
      });
      setMessage(`Restocked ${res.data.product.name} successfully!`);
    } catch (err) {
      setMessage("Error restocking product");
    }
  };

  return (
    <div style={{ maxWidth: 600, margin: "50px auto" }}>
      <h2>Restock Product</h2>
      <form onSubmit={handleRestock}>
        <div>
          <select value={selectedId} onChange={(e) => setSelectedId(e.target.value)} required>
            <option value="">Select product</option>
            {products.map((p) => (
              <option key={p.id} value={p.id}>{p.name} (Stock: {p.stock_qty})</option>
            ))}
          </select>
        </div>
        <div>
          <input type="number" placeholder="Quantity" value={quantity} onChange={(e) => setQuantity(e.target.value)} required />
        </div>
        <div>
          <input type="number" placeholder="Cost Price" value={costPrice} onChange={(e) => setCostPrice(e.target.value)} required />
        </div>
        <div>
          <input type="number" placeholder="Selling Price" value={sellingPrice} onChange={(e) => setSellingPrice(e.target.value)} required />
        </div>
        <button type="submit">Restock</button>
      </form>
      {message && <p>{message}</p>}
    </div>
  );
}

export default RestockProduct;
